-- 71 The Quest Journal: the quest log is entity-UI text with markup
-- ("rich": true), its footer a .gui Text node whose markup wraps template
-- variables, and the letter a ui_text with a typewriter (reveal_speed): set
-- a new letter and it writes itself out again. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/71-the-quest-journal.scene"
local LETTERS = {
    "My dear [color=#2a4f86]Edwin[/color],\n\nThe [color=#9a2a1a]wyrm[/color] stirs again.[pause=0.6]\nSmoke over [color=#2a4f86]Greymoor[/color] at\ndawn, and the river runs warm.\n\nBring the [color=#7a4f00]Gilded Key[/color][pause=0.4]\nand come before the moon\nis full.\n\n[color=#2a4f86][b]- Ilse[/b][/color]",
    "Edwin,\n\n[color=#3d6b25]Old Mara[/color] says the\ndraughts must steep three\nnights.[pause=0.6] Not two.[pause=0.5] [shake]Three.[/shake]\n\nShe sends a [icon=sprites/journal/potion.png] for\nthe road, and her thanks.\n\n[color=#2a4f86][b]- Tomas[/b][/color]",
    "To whoever finds this,\n\nthe bells beneath the crypt\nring for [color=#9a2a1a]no one[/color] living.[pause=0.8]\n\nDo not open the [color=#9a2a1a]third[/color]\ndoor. I did.\n\n[color=#9a2a1a]- a friend[/color]",
}
local SPEED = 26
local captions = true
local letter, glow
local which, shown, t = 1, 0, 0

-- How long a letter takes to write out: its characters (markup aside) at
-- SPEED a second, plus its pauses.
local function duration(s)
    local pauses = 0
    for p in string.gmatch(s, "%[pause=([%d%.]+)%]") do pauses = pauses + tonumber(p) end
    local plain = string.gsub(s, "%[[^%]]*%]", "")
    return #plain / SPEED + pauses
end

local function next_letter()
    which = which % #LETTERS + 1
    UI.set_text(letter, LETTERS[which])
    shown = 0
end

function init(entity)
    letter = Entity.find_by_name("Letter")
    glow = Entity.find_by_name("CandleGlow")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt
    shown = shown + dt
    -- A letter stays on the page a few seconds once it is written.
    if Input.is_key_just_pressed("Space") or shown > duration(LETTERS[which]) + 5 then next_letter() end
    -- The candle flickers.
    local k = 0.3 + 0.05 * math.sin(t * 7.3) + 0.04 * math.sin(t * 13.1 + 1)
    Sprite.set_color(glow, 1.0, 0.52, 0.18, k)
end
